func New(cfg *config.Config) Model {
	s := spinner.New()
	s.Spinner = spinner.Dot
	s.Style = theme.SpinnerStyle()

	it := datatable.New(datatable.Config[imageRow]{
		Columns:    imageColumns(),
		SortColumn: imageColumnName,
		// A pulling placeholder row carries no Image yet, so its ID is empty —
		// falling back to the name keeps two concurrent pulls from colliding
		// on the same key.

	case jobs.ChangedMsg:
		return m.handleJobsChanged(msg)

	case spinner.TickMsg:
		var cmds []tea.Cmd
		// The tables' frames turn while anything is running on a row, which is
		// not the same condition as the view's own spinner: the lists are
		// loaded and on screen while an image is removed.
		busy := m.advanceBusySpinners()
		if busy || m.loading || m.loadingNets || m.loadingVols || m.loadingRegs {
			var cmd tea.Cmd
			m.spinner, cmd = m.spinner.Update(msg)
			m.spinnerFrameIdx = (m.spinnerFrameIdx + 1) % len(spinner.Dot.Frames)
			// A tab's load is reported in the footer, so the frame has to reach
			// it — a spinner stuck on frame zero reads as a hang.
			m.footer.SetSpinnerFrame(m.spinner.View())
			cmds = append(cmds, cmd)
		}
		if m.registryBrowser != nil {
			var cmd tea.Cmd
		{Key: "Components", Value: fmt.Sprintf("%d", len(m.components)), Style: theme.HeaderValueStyle},
	}
}

// View renders the view
func (m Model) View() string {
	// Form mode - overlay
	if m.componentForm != nil {
		return m.componentForm.View()
	}

	// Confirmation mode - overlay
	if m.confirmModal != nil {
		return lipgloss.Place(
			m.width,
			m.height,
			lipgloss.Center,
			lipgloss.Center,
			m.confirmModal.View(),
			lipgloss.WithWhitespaceBackground(theme.ColorBackground),
		)
	}

	// Content - DYNAMIC HEIGHT that fills exactly the available space
	if m.error != "" {
		return m.renderError()
	}
	return m.renderTable()
}

func (m Model) renderError() string {
	msg := fmt.Sprintf("✗ Error: %s", m.error)
	return lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Padding(2, 4).
		Foreground(theme.ColorError).
		// Adopted whole, ID included: the timer that will expire it was built
		// with that ID by the sender, and re-numbering it here would leave a
		// message nothing ever clears.
		f.text = msg.Text
		f.level = msg.Level
		f.id = msg.ID
		return true

	case ClearFooterMsg:
		if f.id == 0 || msg.ID != f.id {
			return false
		}
		f.Clear()
		return true
	}
	return false
}

